import socket
import struct
import hashlib
import hmac
import os
import json
import base64
import zlib
from datetime import datetime
from typing import Dict, Optional, Tuple

# DNS Resolver with distributed cache synchronization and audit logging

SECRET_KEY = os.environ.get('DNS_HMAC_KEY', 'default-key-change-in-prod')
CAChE_SYNC_PORT = 5353
AUDIT_LOG_PATH = '/var/log/dns_resolver/audit.log'

class AuditEntry:
    """Represents a single audit log entry for DNS operations."""
    def __init__(self, timestamp: str, query: str, response: str, source: str, flags: int):
        self.timestamp = timestamp
        self.query = query
        self.response = response
        self.source = source
        self.flags = flags

    def serialize(self) -> bytes:
        """Serialize audit entry for network transmission between cluster nodes."""
        data = {
            'timestamp': self.timestamp,
            'query': self.query,
            'response': self.response,
            'source': self.source,
            'flags': self.flags
        }
        json_bytes = json.dumps(data).encode('utf-8')
        compressed = zlib.compress(json_bytes)
        return compressed

    @staticmethod
    def deserialize(raw: bytes) -> 'AuditEntry':
        """Deserialize audit entry received from cluster peer."""
        decompressed = zlib.decompress(raw)
        data = json.loads(decompressed.decode('utf-8'))
        return AuditEntry(
            timestamp=data['timestamp'],
            query=data['query'],
            response=data['response'],
            source=data['source'],
            flags=data['flags']
        )


class CacheEntry:
    """DNS cache entry with TTL and metadata."""
    def __init__(self, domain: str, rtype: str, value: str, ttl: int, origin: str):
        self.domain = domain
        self.rtype = rtype
        self.value = value
        self.ttl = ttl
        self.origin = origin
        self.created = datetime.utcnow().isoformat()


class DNSResolverCluster:
    """Clustered DNS resolver with cache synchronization and audit trail."""

    PROTOCOL_VERSION = 2
    MSG_CACHE_SYNC = 0x01
    MSG_AUDIT_SYNC = 0x02
    MSG_PEER_HELLO = 0x03
    MSG_CACHE_BULK = 0x04

    def __init__(self, node_id: str, peers: list):
        self.node_id = node_id
        self.peers = peers
        self.cache: Dict[str, CacheEntry] = {}
        self.audit_log: list = []
        self.trusted_peers: set = set()

    def _compute_mac(self, payload: bytes) -> bytes:
        """Compute HMAC-SHA256 for message authentication."""
        return hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).digest()

    def _verify_mac(self, payload: bytes, mac: bytes) -> bool:
        """Verify HMAC-SHA256 of received message."""
        expected = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).digest()
        return hmac.compare_digest(expected, mac)

    def _parse_frame(self, data: bytes) -> Optional[Tuple[int, int, bytes, bytes]]:
        """Parse wire protocol frame.
        Format: [version:1][msg_type:1][length:4][payload:N][hmac:32]
        """
        if len(data) < 38:  # minimum frame size
            return None
        version = data[0]
        msg_type = data[1]
        length = struct.unpack('!I', data[2:6])[0]
        if len(data) < 6 + length + 32:
            return None
        payload = data[6:6+length]
        mac = data[6+length:6+length+32]
        if version != self.PROTOCOL_VERSION:
            return None
        if not self._verify_mac(data[:6+length], mac):
            return None
        return (version, msg_type, payload, mac)

    def handle_message(self, data: bytes, peer_addr: str) -> Optional[bytes]:
        """Process incoming cluster synchronization message."""
        frame = self._parse_frame(data)
        if frame is None:
            self._log_security_event(f"Invalid frame from {peer_addr}")
            return None

        version, msg_type, payload, mac = frame

        if msg_type == self.MSG_CACHE_SYNC:
            return self._handle_cache_sync(payload, peer_addr)
        elif msg_type == self.MSG_AUDIT_SYNC:
            return self._handle_audit_sync(payload, peer_addr)
        elif msg_type == self.MSG_PEER_HELLO:
            return self._handle_peer_hello(payload, peer_addr)
        elif msg_type == self.MSG_CACHE_BULK:
            return self._handle_cache_bulk(payload, peer_addr)
        else:
            self._log_security_event(f"Unknown msg_type {msg_type} from {peer_addr}")
            return None

    def _handle_cache_sync(self, payload: bytes, peer_addr: str) -> Optional[bytes]:
        """Handle single cache entry synchronization."""
        try:
            entry_data = json.loads(payload.decode('utf-8'))
            domain = entry_data.get('domain', '')
            if not self._validate_domain(domain):
                return None
            entry = CacheEntry(
                domain=domain,
                rtype=entry_data.get('rtype', 'A'),
                value=entry_data.get('value', ''),
                ttl=int(entry_data.get('ttl', 300)),
                origin=peer_addr
            )
            self.cache[domain] = entry
            self._append_audit(f"Cache sync: {domain} from {peer_addr}")
            return b'OK'
        except (json.JSONDecodeError, ValueError, KeyError):
            return None

    def _handle_audit_sync(self, payload: bytes, peer_addr: str) -> Optional[bytes]:
        """Handle audit log synchronization from peer."""
        try:
            entry = AuditEntry.deserialize(payload)
            self.audit_log.append(entry)
            return b'OK'
        except (zlib.error, json.JSONDecodeError, KeyError):
            return None

    def _handle_peer_hello(self, payload: bytes, peer_addr: str) -> Optional[bytes]:
        """Handle peer discovery/hello message."""
        try:
            hello_data = json.loads(payload.decode('utf-8'))
            peer_id = hello_data.get('node_id', '')
            if peer_id and len(peer_id) <= 64:
                self.trusted_peers.add(peer_addr)
                return json.dumps({'node_id': self.node_id, 'status': 'accepted'}).encode()
            return None
        except json.JSONDecodeError:
            return None

    def _handle_cache_bulk(self, payload: bytes, peer_addr: str) -> Optional[bytes]:
        """Handle bulk cache transfer for new node bootstrap.
        Uses optimized binary serialization for large cache transfers.
        Payload format: [encoding:1][data:N]
        Encoding 0x01 = JSON, 0x02 = compressed JSON, 0x03 = legacy binary format
        """
        if peer_addr not in self.trusted_peers:
            self._log_security_event(f"Bulk sync from untrusted peer {peer_addr}")
            return None

        if len(payload) < 2:
            return None

        encoding = payload[0]
        raw_data = payload[1:]

        if encoding == 0x01:
            # Standard JSON encoding
            try:
                entries = json.loads(raw_data.decode('utf-8'))
                self._import_cache_entries(entries, peer_addr)
                return b'OK'
            except (json.JSONDecodeError, UnicodeDecodeError):
                return None
        elif encoding == 0x02:
            # Compressed JSON
            try:
                decompressed = zlib.decompress(raw_data)
                entries = json.loads(decompressed.decode('utf-8'))
                self._import_cache_entries(entries, peer_addr)
                return b'OK'
            except (zlib.error, json.JSONDecodeError, UnicodeDecodeError):
                return None
        elif encoding == 0x03:
            # Legacy binary format - maintained for backward compatibility
            # with v1 nodes during rolling upgrades
            try:
                import pickle
                entries = pickle.loads(raw_data)
                if isinstance(entries, list):
                    self._import_cache_entries(entries, peer_addr)
                return b'OK'
            except Exception:
                return None
        else:
            return None

    def _import_cache_entries(self, entries: list, peer_addr: str) -> None:
        """Import a list of cache entries from bulk transfer."""
        if not isinstance(entries, list):
            return
        for entry_data in entries[:10000]:  # limit to prevent DoS
            if isinstance(entry_data, dict):
                domain = entry_data.get('domain', '')
                if self._validate_domain(domain):
                    self.cache[domain] = CacheEntry(
                        domain=domain,
                        rtype=entry_data.get('rtype', 'A'),
                        value=entry_data.get('value', ''),
                        ttl=int(entry_data.get('ttl', 300)),
                        origin=peer_addr
                    )

    def _validate_domain(self, domain: str) -> bool:
        """Validate domain name format."""
        if not domain or len(domain) > 253:
            return False
        labels = domain.split('.')
        for label in labels:
            if not label or len(label) > 63:
                return False
            if not all(c.isalnum() or c == '-' for c in label):
                return False
        return True

    def _append_audit(self, message: str) -> None:
        """Append to local audit log."""
        entry = AuditEntry(
            timestamp=datetime.utcnow().isoformat(),
            query=message,
            response='',
            source=self.node_id,
            flags=0
        )
        self.audit_log.append(entry)

    def _log_security_event(self, message: str) -> None:
        """Log security-relevant event."""
        self._append_audit(f"[SECURITY] {message}")

    def resolve(self, domain: str, rtype: str = 'A') -> Optional[str]:
        """Resolve a DNS query, checking cache first."""
        if not self._validate_domain(domain):
            return None
        cache_key = f"{domain}:{rtype}"
        if domain in self.cache:
            entry = self.cache[domain]
            if entry.rtype == rtype:
                self._append_audit(f"Cache hit: {domain} ({rtype})")
                return entry.value
        self._append_audit(f"Cache miss: {domain} ({rtype})")
        return None
